function vid(u){const m=u.match(/(?:v=|youtu\.be\/|\/(?:shorts|live)\/)([\w-]{11})/i);return m&&m[1]}
function xml(s){return s.replace(/&amp;/g,'&').replace(/&#39;/g,"'").replace(/&quot;/g,'"').replace(/&lt;/g,'<').replace(/&gt;/g,'>')}
function stamp(s){return `[${new Date(s*1000).toISOString().slice(11,19)}]`}
async function extract(url,language='auto',timestamps=false,paragraphs=true){const id=vid(url);if(!id)throw new Error('Enter a valid YouTube watch, short, live, or youtu.be URL.');const page=await fetch('https://www.youtube.com/watch?v='+id).then(r=>r.text());const match=page.match(/"captionTracks":(\[[^\]]+\])/);if(!match)throw new Error('No accessible transcript was found for this video.');let tracks=JSON.parse(match[1].replace(/\\u0026/g,'&'));if(language!=='auto')tracks=tracks.sort((a,b)=>(a.languageCode===language?-1:0)-(b.languageCode===language?-1:0));const cap=await fetch(tracks[0].baseUrl).then(r=>r.text());const items=[...cap.matchAll(/<text start="([^"]+)" dur="([^"]+)">(.*?)<\/text>/gs)].map(m=>({text:xml(m[3].replace(/<[^>]+>/g,'')),start:+m[1],duration:+m[2]}));if(!items.length)throw new Error('The transcript was empty or unavailable.');const transcript=timestamps?items.map(x=>stamp(x.start)+' '+x.text).join('\n'):paragraphs?items.map(x=>x.text).join('\n\n'):items.map(x=>x.text).join(' ');return {video_id:id,video_url:'https://www.youtube.com/watch?v='+id,title:'Transcript ready',channel:'YouTube',thumbnail:'https://i.ytimg.com/vi/'+id+'/hqdefault.jpg',language:tracks[0].languageCode,available_languages:tracks.map(x=>x.languageCode),items,original:items.map(x=>x.text).join('\n'),transcript,word_count:transcript.split(/\s+/).filter(Boolean).length}}
export default {async fetch(request,env){const url=new URL(request.url);if(url.pathname==='/api/health')return Response.json({ok:true});if(url.pathname==='/api/extract'&&request.method==='POST'){try{const b=await request.json(),d=await extract(b.url,b.language,b.include_timestamps,b.add_paragraphs);return Response.json(d)}catch(e){return Response.json({detail:e.message},{status:422})}}if(url.pathname==='/'||url.pathname==='/index.html')return env.ASSETS.fetch(request);return new Response('Not found',{status:404})}}
